package com.sentinelai.graph.api;
import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api/v1/graph") public class GraphController {
 @GetMapping public GraphResponse graph(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size,Authentication auth){String tenant=tenant(auth);int safeSize=Math.min(100,Math.max(1,size));var nodes=List.of(new Node("account_demo_001","ACCOUNT","Conta sintética 001"),new Node("device_demo_001","DEVICE","Dispositivo sintético 001"),new Node("session_demo_001","SESSION","Sessão sintética 001"),new Node("event_demo_001","EVENT","Evento sintético 001"));var edges=List.of(new Edge("account_demo_001-device_demo_001","account_demo_001","device_demo_001","USED_DEVICE","Evento sintético 001","HIGH"),new Edge("account_demo_001-session_demo_001","account_demo_001","session_demo_001","INITIATED_SESSION","Evento sintético 001","MEDIUM"),new Edge("session_demo_001-event_demo_001","session_demo_001","event_demo_001","TRIGGERED_EVENT","Evento sintético 001","MEDIUM"));return new GraphResponse(tenant,nodes.subList(0,Math.min(safeSize,nodes.size())),edges,Math.max(0,page),safeSize,nodes.size());}
 private String tenant(Authentication a){if(a instanceof JwtAuthenticationToken j){String t=j.getToken().getClaimAsString("tenant_id");if(t!=null&&!t.isBlank())return t;}throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant missing");}
 public record Node(String id,String type,String label){} public record Edge(String id,String source,String target,String relation,String evidenceSource,String confidence){} public record GraphResponse(String tenantId,List<Node> nodes,List<Edge> edges,int page,int size,int totalNodes){}
}
